package com.tiny.browser;import android.app.*;import android.webkit.*;import android.widget.*;public class MainActivity extends Activity{protected void onCreate(android.os.Bundle b){super.onCreate(b);LinearLayout l=new LinearLayout(this);l.setOrientation(1);EditText u=new EditText(this);u.setSingleLine();WebView w=new WebView(this);l.addView(u,-1,-2);l.addView(w,-1,-1);setContentView(l);u.setOnEditorActionListener((v,a,e)->{w.loadUrl(u.getText().toString().trim());return true;});}}
